{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { BRANDS } from "@/data/catalog";
import { COMPANY } from "@/data/company";

export const Route = createFileRoute("/brands")({
  head: () => ({
    meta: [
      { title: "Manufacturers & Brands We Stock | Pickrel Brothers, Dayton OH" },
      {
        name: "description",
        content:
          "Browse the Pickrel Brothers line card: Delta, Moen, Sloan, Zurn, Watts, Viega, Victaulic, Nibco, Grundfos, Bell & Gossett, Rheem and many more.",
      },
      { property: "og:title", content: "Manufacturers & Brands | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "The manufacturers behind our plumbing, HVAC, pipe, valve and industrial product lines.",
      },
    ],
  }),
  component: BrandsPage,
});

function BrandsPage() {
  const [q, setQ] = useState("");
  const [cat, setCat] = useState("");

  const allCats = useMemo(
    () => [...new Set(BRANDS.flatMap((b) => b.categories))].sort(),
    [],
  );

  const filtered = BRANDS.filter(
    (b) =>
      b.name.toLowerCase().includes(q.trim().toLowerCase()) &&
      (cat === "" || b.categories.includes(cat)),
  );

  return (
    <div className="container-page py-10">
      <h1 className="font-display text-3xl font-bold uppercase text-navy">Brands We Distribute</h1>
      <p className="mt-2 max-w-3xl text-muted-foreground">
        Pickrel Brothers represents the manufacturers listed on our line card — and we can source many
        that aren't listed here.
      </p>

      <div className="mt-6 flex flex-wrap gap-3">
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Search manufacturers"
          aria-label="Search manufacturers"
          className="h-11 w-full max-w-sm rounded-md border border-input bg-card px-4 text-sm text-foreground"
        />
        <select
          value={cat}
          onChange={(e) => setCat(e.target.value)}
          aria-label="Filter by product line"
          className="h-11 rounded-md border border-input bg-card px-3 text-sm text-foreground"
        >
          <option value="">All product lines</option>
          {allCats.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
      </div>

      <div className="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {filtered.map((b) => (
          <Link
            key={b.slug}
            to="/products"
            search={{ q: "", category: "", brand: b.name }}
            className="rounded-md border border-border bg-card p-5 shadow-card transition-colors hover:border-sky"
          >
            <h2 className="font-display text-lg font-bold uppercase text-navy">{b.name}</h2>
            <p className="mt-1 text-xs text-muted-foreground">{b.categories.join(" · ")}</p>
          </Link>
        ))}
      </div>

      {filtered.length === 0 && (
        <p className="mt-8 text-sm text-muted-foreground">No manufacturers match that filter.</p>
      )}

      <section className="mt-12 rounded-md border-2 border-sky bg-sky-soft p-8 text-center">
        <h2 className="font-display text-2xl font-bold uppercase text-navy">
          Can't find what you're looking for?
        </h2>
        <p className="mt-2 text-lg font-semibold text-navy">Just call.</p>
        <p className="mx-auto mt-2 max-w-xl text-sm text-navy-muted">
          We locate manufacturers and products beyond our line card every day. Tell us what you need.
        </p>
        <div className="mt-5 flex flex-wrap justify-center gap-3">
          <a
            href={COMPANY.phoneHref}
            className="rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
          >
            Call {COMPANY.phone}
          </a>
          <Link
            to="/contact"
            className="rounded-md border-2 border-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy hover:bg-card"
          >
            Contact us
          </Link>
        </div>
      </section>
    </div>
  );
}
